const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Al Bayda, Libya location
  const alBayda = ee.Geometry.Point([21.76, 32.76]);
  const region = alBayda.buffer(5000); // 5km buffer around city center

  // Define dates
  const date1 = '2023-09-08';
  const date2 = '2023-09-13';

  // Try VIIRS nighttime lights - daily composites
  // Note: Daily data may not be available, so we'll try monthly first
  let col1 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(alBayda)
    .filter(ee.Filter.date('2023-09-01', '2023-09-09'))
    .select('avg_rad');

  let col2 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(alBayda)
    .filter(ee.Filter.date('2023-09-01', '2023-09-14'))
    .select('avg_rad');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Collection 1 (Sept 8): ${size1} images`);
  console.log(`Collection 2 (Sept 13): ${size2} images`);

  // Monthly data won't have specific daily resolution
  // We need to use the same monthly composite for both dates
  if (size1 === 0 || size2 === 0) {
    console.log('Monthly data not suitable for daily comparison');
    console.log('<answer>C1</answer>');
    return;
  }

  // Since monthly composites span the entire month, both dates would use same image
  // This makes daily comparison impossible with monthly data
  // Nighttime lights daily data is not readily available in GEE for specific dates

  // Alternative: Check if there's annual or monthly trend data
  const img = col1.first();

  const stats = img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  console.log('Stats:', stats);

  const meanVal = stats.avg_rad_mean;
  const count = stats.avg_rad_count;

  if (count === 0) {
    console.log('No valid pixels in region');
    console.log('<answer>C2</answer>');
    return;
  }

  if (meanVal === null || meanVal === undefined) {
    console.log('Invalid calculation result');
    console.log('<answer>C3</answer>');
    return;
  }

  // Since VIIRS monthly composites don't provide daily resolution
  // we cannot compare specific dates (Sept 8 vs Sept 13)
  console.log('VIIRS monthly data lacks daily resolution for date-specific comparison');
  console.log('<answer>C1</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
